    if(!coordinator.SwitchClip(root,controller,skeleton,map,map.compatibility,clip,settings))return Fail("clip switch failed");pose=Pose(skeleton,clip,.1);if(!coordinator.PreviewTick(root,controller,skeleton,{43,.1},pose,empty,transaction,&preview)||preview.rootMotion.status!=RootMotionStatus3D::NoMotion||!coordinator.Commit(transaction,pose,&committed))return Fail("clip switch anchor failed");
